#!/bin/bash

# This script is basically fully generated by Gemini.
# I would have made it myself, but Google's search AI gave me a first version,
# so I figured I'll that AI fix it from that point.

GREEN='\033[0;32m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
NC='\033[0m'

cleanup() {
    rm -f ffmpeg2pass-0.log ffmpeg2pass-0.log.mbtree x265_2pass.log x265_2pass.log.cutree x265_2pass.log.mbtree 2>/dev/null
}
trap cleanup EXIT INT TERM

CODEC_MODE="legacy"
PREFER_MODE="resolution"
INPUT_FILE=""

while [[ $# -gt 0 ]]; do
    case "$1" in
        -legacy) CODEC_MODE="legacy"; shift ;;
        -modern) CODEC_MODE="modern"; shift ;;
        -prefer-fps) PREFER_MODE="framerate"; shift ;;
        -prefer-res) PREFER_MODE="resolution"; shift ;;
        -*) echo -e "${YELLOW}Unknown option: $1${NC}"; exit 1 ;;
        *) INPUT_FILE="$1"; shift ;;
    esac
done

if [ -z "$INPUT_FILE" ]; then
    echo -e "${YELLOW}Usage: $0 [-legacy|-modern] [-prefer-res|-prefer-fps] \"video.mp4\"${NC}"
    exit 1
fi

DURATION=$(ffprobe -i "$INPUT_FILE" -show_entries format=duration -v quiet -of default=noprint_wrappers=1:nokey=1)
FPS_RAW=$(ffprobe -v error -select_streams v:0 -show_entries stream=r_frame_rate -of default=nokey=1:noprint_wrappers=1 "$INPUT_FILE")
FPS=$(echo "$FPS_RAW" | awk -F'/' '{if ($2 != 0) print int($1/$2); else print int($1)}')

if [[ -z "$DURATION" ]]; then
    echo -e "${YELLOW}Error: Could not determine video parameters.${NC}"; exit 1
fi

AUDIO_BITRATE=128
TOTAL_BITRATE=$(echo "$DURATION" | awk '{print int(77824 / $1)}')
VIDEO_BITRATE=$((TOTAL_BITRATE - AUDIO_BITRATE))
if [ "$VIDEO_BITRATE" -lt 50 ]; then VIDEO_BITRATE=50; fi

EFFECTIVE_BITRATE=$VIDEO_BITRATE
if [ "$CODEC_MODE" == "modern" ]; then EFFECTIVE_BITRATE=$((VIDEO_BITRATE * 15 / 10)); fi

FRAMERATE_FLAG=()
FPS_DROPPED=false

if [ "$FPS" -gt 30 ]; then
    if [ "$PREFER_MODE" == "resolution" ] && [ "$EFFECTIVE_BITRATE" -lt 1500 ]; then
        FRAMERATE_FLAG=("-r" "30")
        FPS_DROPPED=true
        EFFECTIVE_BITRATE=$((EFFECTIVE_BITRATE * 13 / 10))
    fi
fi

VF_SCALE=""
TARGET_RES="Original"
if [ "$EFFECTIVE_BITRATE" -lt 300 ]; then
    VF_SCALE="scale='min(640,iw)':'min(640,ih)':force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2"
    TARGET_RES="360p"
elif [ "$EFFECTIVE_BITRATE" -lt 700 ]; then
    VF_SCALE="scale='min(854,iw)':'min(854,ih)':force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2"
    TARGET_RES="480p"
elif [ "$EFFECTIVE_BITRATE" -lt 1400 ]; then
    VF_SCALE="scale='min(1280,iw)':'min(1280,ih)':force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2"
    TARGET_RES="720p"
elif [ "$EFFECTIVE_BITRATE" -lt 3200 ]; then
    VF_SCALE="scale='min(1920,iw)':'min(1920,ih)':force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2"
    TARGET_RES="1080p"
fi

echo -e "${BLUE}Video Duration:${NC} ${DURATION}s (${FPS} fps)"
echo -e "${BLUE}Target Video Bitrate:${NC} ${VIDEO_BITRATE}k (Targeting ~9.5MB)"
echo -e "${BLUE}Resolution Target:${NC} ${TARGET_RES}"
if [ "$FPS_DROPPED" = true ]; then
    echo -e "${YELLOW}Framerate Target:${NC} Reduced to 30fps (Favoring Resolution)"
else
    echo -e "${BLUE}Framerate Target:${NC} Retained ${FPS}fps"
fi

# Standard FFmpeg output clean-up flags
FFMPEG_QUIET=(-hide_banner -loglevel error -stats)

BASE_CMD=(ffmpeg -y -i "$INPUT_FILE" "${FFMPEG_QUIET[@]}")
if [ -n "$VF_SCALE" ]; then BASE_CMD+=("-vf" "$VF_SCALE"); fi
if [ ${#FRAMERATE_FLAG[@]} -gt 0 ]; then BASE_CMD+=("${FRAMERATE_FLAG[@]}"); fi

if [ "$CODEC_MODE" == "legacy" ]; then
    OUTPUT_FILE="${INPUT_FILE%.*} (compressed_x264).mp4"
    ANALYSIS_CMD=("${BASE_CMD[@]}" -c:v libx264 -b:v "${VIDEO_BITRATE}k" -preset slower -fastfirstpass 1 -pass 1 -an -f mp4 /dev/null)
    RENDER_CMD=("${BASE_CMD[@]}" -c:v libx264 -b:v "${VIDEO_BITRATE}k" -preset slower -pass 2 -c:a aac -b:a "${AUDIO_BITRATE}k" "$OUTPUT_FILE")
else
    OUTPUT_FILE="${INPUT_FILE%.*} (compressed_x265).mp4"
    ANALYSIS_CMD=("${BASE_CMD[@]}" -c:v libx265 -b:v "${VIDEO_BITRATE}k" -preset slower -x265-params pass=1:slow-firstpass=0 -an -f mp4 /dev/null)
    RENDER_CMD=("${BASE_CMD[@]}" -c:v libx265 -b:v "${VIDEO_BITRATE}k" -preset slower -x265-params pass=2 -c:a aac -b:a "${AUDIO_BITRATE}k" "$OUTPUT_FILE")
fi

echo -e "\n${CYAN}Starting Analysis Pass...${NC}"
"${ANALYSIS_CMD[@]}" || { echo -e "${YELLOW}Analysis Pass failed!${NC}"; exit 1; }

echo -e "\n${YELLOW}Analysis Complete. Starting Render Pass...${NC}"
"${RENDER_CMD[@]}" || { echo -e "${YELLOW}Render Pass failed!${NC}"; exit 1; }

echo -e "\n${GREEN}✔ Complete! Saved as: $OUTPUT_FILE${NC}\n"
